/**
 * Task ID 생성 함수
 * @param id - 원본 문자열 ID
 * @returns 브랜드 타입이 적용된 TaskId
 * @example
 * ```typescript
 * const taskId = createTaskId('task-001');
 * // 타입: TaskId
 * ```
 */
export function createTaskId(id: string): TaskId {
  if (!/^task-.+/.test(id)) {
    throw new Error("TaskId must start with 'task-' followed by an identifier");
  }
  return id as TaskId;
}

